"""Snap spans to a fixed clock step and label them for payroll."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span


def _check_step(step_minutes: int) -> None:
    if step_minutes <= 0 or 60 % step_minutes:
        raise ValueError(f"step must be positive and divide an hour: {step_minutes}")


def _round_minute(minute: int, step_minutes: int) -> int:
    """Nearest multiple of the step. Halfway points round up."""
    return ((minute + step_minutes // 2) // step_minutes) * step_minutes


def _snap(span: Span, step_minutes: int) -> Span:
    start = _round_minute(span.start, step_minutes)
    end = _round_minute(span.end, step_minutes)
    return Span(start, end)


def _duration_text(span: Span) -> str:
    hours, minutes = divmod(span.minutes, 60)
    return f"{hours}h {minutes}m"


# ---
def label_rounded_spans(spans: Iterable[Span], step_minutes: int) -> List[str]:
    """Snap each span to the step and label it, such as 09:00-17:15 (8h 15m)."""
    _check_step(step_minutes)
    snapped = [_snap(span, step_minutes) for span in spans]
    return [f"{format_span(item)} ({_duration_text(item)})" for item in snapped]

