import unittest

from hourglass.parsing import parse_span
from hourglass.rounding import label_rounded_spans


class LabelTests(unittest.TestCase):
    def test_snaps_to_nearest_step(self):
        labels = label_rounded_spans([parse_span("08:58-17:17")], 15)
        self.assertEqual(labels, ["09:00-17:15 (8h 15m)"])

    def test_halfway_points_round_up(self):
        labels = label_rounded_spans([parse_span("09:05-09:15")], 10)
        self.assertEqual(labels, ["09:10-09:20 (0h 10m)"])

    def test_end_of_day_is_kept(self):
        labels = label_rounded_spans([parse_span("16:55-23:58")], 15)
        self.assertEqual(labels, ["17:00-24:00 (7h 0m)"])

    def test_hour_step_is_allowed(self):
        labels = label_rounded_spans([parse_span("09:20-10:40")], 60)
        self.assertEqual(labels, ["09:00-11:00 (2h 0m)"])

    def test_step_of_one_changes_nothing(self):
        labels = label_rounded_spans([parse_span("09:01-10:59")], 1)
        self.assertEqual(labels, ["09:01-10:59 (1h 58m)"])

    def test_keeps_order_of_spans(self):
        first = parse_span("09:00-10:00")
        second = parse_span("13:10-14:00")
        labels = label_rounded_spans([first, second], 30)
        self.assertEqual(labels, ["09:00-10:00 (1h 0m)", "13:00-14:00 (1h 0m)"])

    def test_no_spans_gives_no_labels(self):
        self.assertEqual(label_rounded_spans([], 15), [])

    def test_bad_steps_are_rejected(self):
        for step in (0, -15, 7, 45, 120):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    label_rounded_spans([parse_span("09:00-10:00")], step)

    def test_span_that_collapses_to_nothing_is_rejected(self):
        with self.assertRaises(ValueError):
            label_rounded_spans([parse_span("09:01-09:04")], 15)
